close() {
  if (this.#isBusy) {
    return;
  }

  this.modal.close();
}

/**
 * Helper function to check if we can safely close the dialog without killing
 * any ongoing operations if the user presses the Escape key.
 */
onBeforeClosing(event) {
  if (this.#isBusy) {
    event.preventDefault();
  }
}
